import * as fs from 'fs';
import * as http from 'http';
import * as path from 'path';
import { watch, FSWatcher } from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { build } from './build';

export interface DevServerOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port?: number;
}

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.mjs': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
};

const LIVE_RELOAD_SCRIPT =
  '<script>(function(){var ws=new WebSocket("ws://"+location.host);ws.onmessage=function(e){if(e.data==="reload"){location.reload();}};})();</script>';

/** Inject the live-reload WebSocket client into an HTML document. */
export function injectLiveReloadScript(html: string): string {
  const bodyTag = html.match(/<\/body\s*>/i);
  if (bodyTag) {
    return html.replace(bodyTag[0], `${LIVE_RELOAD_SCRIPT}${bodyTag[0]}`);
  }
  return html + LIVE_RELOAD_SCRIPT;
}

/**
 * A development server that serves the built site from the output directory,
 * watches the content and templates directories for changes, rebuilds on
 * change, and notifies connected browsers to reload.
 */
export class DevServer {
  private server: http.Server;
  private wss: WebSocketServer;
  private watcher: FSWatcher;
  private ready: Promise<void>;
  private options: { contentDir: string; outputDir: string; templatesDir: string };
  private port: number;
  private rebuildTimer: NodeJS.Timeout | null = null;

  constructor(options: DevServerOptions) {
    this.options = {
      contentDir: options.contentDir,
      outputDir: options.outputDir,
      templatesDir: options.templatesDir ?? './templates',
    };
    this.port = options.port ?? 3000;

    this.server = http.createServer((req, res) => this.handleRequest(req, res));
    this.wss = new WebSocketServer({ server: this.server });

    this.watcher = watch([this.options.contentDir, this.options.templatesDir], {
      ignoreInitial: true,
    });
    this.ready = new Promise((resolve) => this.watcher.once('ready', () => resolve()));
    this.watcher.on('all', () => this.scheduleRebuild());
  }

  private scheduleRebuild(): void {
    if (this.rebuildTimer) {
      clearTimeout(this.rebuildTimer);
    }
    this.rebuildTimer = setTimeout(() => {
      this.rebuildTimer = null;
      this.rebuild();
    }, 50);
  }

  private rebuild(): void {
    try {
      build({
        contentDir: this.options.contentDir,
        outputDir: this.options.outputDir,
        templatesDir: this.options.templatesDir,
      });
    } catch (err) {
      console.error('Build failed:', err);
      return;
    }
    for (const client of this.wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  private handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
    const rawPath = (req.url || '/').split('?')[0];
    let pathname: string;
    try {
      pathname = decodeURIComponent(rawPath);
    } catch {
      res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Bad Request');
      return;
    }

    if (pathname === '/') {
      pathname = '/index.html';
    }

    const outputRoot = path.resolve(this.options.outputDir);
    const resolved = path.resolve(outputRoot, pathname.replace(/^\/+/, ''));

    if (resolved !== outputRoot && !resolved.startsWith(outputRoot + path.sep)) {
      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Forbidden');
      return;
    }

    fs.readFile(resolved, (err, data) => {
      if (err) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Not Found');
        return;
      }

      const ext = path.extname(resolved).toLowerCase();
      const contentType = MIME_TYPES[ext] || 'application/octet-stream';
      const body = ext === '.html' ? Buffer.from(injectLiveReloadScript(data.toString('utf8'))) : data;

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(body);
    });
  }

  /** Perform an initial build, start listening, and resolve to the bound port. */
  start(): Promise<number> {
    this.rebuild();
    return new Promise((resolve, reject) => {
      this.server.once('error', reject);
      this.server.listen(this.port, async () => {
        await this.ready;
        const address = this.server.address();
        const port = typeof address === 'object' && address !== null ? address.port : this.port;
        resolve(port);
      });
    });
  }

  /** Stop the watcher, disconnect clients, and close the servers. */
  async close(): Promise<void> {
    if (this.rebuildTimer) {
      clearTimeout(this.rebuildTimer);
      this.rebuildTimer = null;
    }
    await this.watcher.close();
    for (const client of this.wss.clients) {
      client.terminate();
    }
    await new Promise<void>((resolve) => this.wss.close(() => resolve()));
    await new Promise<void>((resolve) => this.server.close(() => resolve()));
  }
}

import { build } from './build';
import { DevServer } from './dev-server';

export interface ParsedArgs {
  command: string;
  content: string;
  output: string;
  templates: string;
  port: number;
}

export function parseArgs(argv: string[]): ParsedArgs {
  const args = argv.slice(2);
  const command = args.find((a) => !a.startsWith('-')) || 'build';
  let content = './content';
  let output = './dist';
  let templates = './templates';
  let port = 3000;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content' || arg === '-c') {
      content = args[i + 1] ?? content;
      i++;
    } else if (arg.startsWith('--content=')) {
      content = arg.slice('--content='.length);
    } else if (arg === '--output' || arg === '-o') {
      output = args[i + 1] ?? output;
      i++;
    } else if (arg.startsWith('--output=')) {
      output = arg.slice('--output='.length);
    } else if (arg === '--templates' || arg === '-t') {
      templates = args[i + 1] ?? templates;
      i++;
    } else if (arg.startsWith('--templates=')) {
      templates = arg.slice('--templates='.length);
    } else if (arg === '--port' || arg === '-p') {
      const value = args[i + 1];
      if (value !== undefined) {
        port = Number(value);
        i++;
      }
    } else if (arg.startsWith('--port=')) {
      port = Number(arg.slice('--port='.length));
    }
  }

  if (Number.isNaN(port)) {
    port = 3000;
  }

  return { command, content, output, templates, port };
}

export function run(argv: string[]): void {
  const { command, content, output, templates, port } = parseArgs(argv);

  if (command === 'build') {
    const result = build({ contentDir: content, outputDir: output, templatesDir: templates });
    console.log(`Built ${result.writtenFiles.length} files into ${result.outputDir}`);
    return;
  }

  if (command === 'serve') {
    const server = new DevServer({
      contentDir: content,
      outputDir: output,
      templatesDir: templates,
      port,
    });
    server
      .start()
      .then((actualPort) => {
        console.log(`Serving ${output} at http://localhost:${actualPort}`);
      })
      .catch((err) => {
        console.error(`Failed to start dev server: ${err.message}`);
        process.exitCode = 1;
      });
    return;
  }

  console.error(`Unknown command: ${command}`);
  console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
  process.exitCode = 1;
}

import * as fs from 'fs';
import * as http from 'http';
import * as os from 'os';
import * as path from 'path';
import WebSocket from 'ws';
import { DevServer, injectLiveReloadScript } from '../src/dev-server';
import { parseArgs } from '../src/cli';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-serve-'));
}

function get(port: number, url: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    http
      .get({ host: 'localhost', port, path: url, headers: { Connection: 'close' } }, (res) => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => (body += chunk));
        res.on('end', () => resolve({ status: res.statusCode ?? 0, body }));
      })
      .on('error', reject);
  });
}

function waitFor(condition: () => boolean, timeoutMs = 5000): Promise<void> {
  return new Promise((resolve, reject) => {
    const start = Date.now();
    const timer = setInterval(() => {
      if (condition()) {
        clearInterval(timer);
        resolve();
      } else if (Date.now() - start > timeoutMs) {
        clearInterval(timer);
        reject(new Error('Timed out waiting for condition'));
      }
    }, 20);
  });
}

describe('injectLiveReloadScript', () => {
  it('injects the reload script before </body>', () => {
    const html = '<html><body><h1>Hi</h1></body></html>';
    const result = injectLiveReloadScript(html);
    expect(result).toContain('WebSocket');
    expect(result).toContain('location.host');
    expect(result).toContain('location.reload()');
    expect(result.indexOf('WebSocket')).toBeLessThan(result.indexOf('</body>'));
    expect(result).toContain('<h1>Hi</h1>');
  });

  it('appends the script when no </body> is present', () => {
    const html = '<h1>Fragment</h1>';
    const result = injectLiveReloadScript(html);
    expect(result).toContain('<h1>Fragment</h1>');
    expect(result).toContain('WebSocket');
    expect(result.endsWith('</script>')).toBe(true);
  });
});

describe('parseArgs serve', () => {
  it('parses the serve command with a default port of 3000', () => {
    const args = parseArgs(['node', 'ssg', 'serve']);
    expect(args.command).toBe('serve');
    expect(args.port).toBe(3000);
  });

  it('parses --port', () => {
    const args = parseArgs(['node', 'ssg', 'serve', '--port', '4321']);
    expect(args.port).toBe(4321);
  });

  it('parses --port=8080', () => {
    const args = parseArgs(['node', 'ssg', 'serve', '--port=8080']);
    expect(args.port).toBe(8080);
  });
});

describe('DevServer', () => {
  it('serves built HTML with an injected live-reload script', async () => {
    const contentDir = makeTempDir();
    const outputDir = makeTempDir();
    fs.writeFileSync(path.join(contentDir, 'hello.md'), '---\ntitle: Hello\n---\n# Hello\n');

    const server = new DevServer({ contentDir, outputDir, port: 0 });
    const port = await server.start();
    try {
      const res = await get(port, '/');
      expect(res.status).toBe(200);
      expect(res.body).toContain('<h1>Hello</h1>');
      expect(res.body).toContain('WebSocket');
    } finally {
      await server.close();
    }
  });

  it('rebuilds and notifies WebSocket clients on file change', async () => {
    const contentDir = makeTempDir();
    const outputDir = makeTempDir();
    const file = path.join(contentDir, 'post.md');
    fs.writeFileSync(file, '---\ntitle: Before\n---\n# Before\n');

    const server = new DevServer({ contentDir, outputDir, port: 0 });
    const port = await server.start();

    const messages: string[] = [];
    const ws = new WebSocket(`ws://localhost:${port}`);
    await new Promise<void>((resolve, reject) => {
      ws.once('open', () => resolve());
      ws.once('error', reject);
    });
    ws.on('message', (data) => messages.push(String(data)));

    const before = await get(port, '/post.html');
    expect(before.body).toContain('Before');

    fs.writeFileSync(file, '---\ntitle: After\n---\n# After\n');

    await waitFor(() => messages.includes('reload'));
    await waitFor(() => fs.readFileSync(path.join(outputDir, 'post.html'), 'utf8').includes('After'));

    ws.terminate();
    await server.close();
  });

  it('serves 404 for missing files', async () => {
    const contentDir = makeTempDir();
    const outputDir = makeTempDir();
    const server = new DevServer({ contentDir, outputDir, port: 0 });
    const port = await server.start();
    try {
      const res = await get(port, '/nope.html');
      expect(res.status).toBe(404);
    } finally {
      await server.close();
    }
  });
});

